function cexp(){const p=S.inC;if(!p)return;const i=S.dist,c=p.cs;if(S.air<1||c.ev[i]<=0)return;S.air--;start("구역 탐색",9,()=>{c.ev[i]--;const L=M("luck");ev(pick(rnd()<Math.min(.9,.5+L)?DEG:DEB));if(S.air<=0)leaveC("산소가 바닥나 수면으로 올라왔다.")})}
