 let act=i<4?bt(`구역 탐색 (15분 · 산소 1) · 남은 ${c.ev[i]}`,"cexp()",z||c.ev[i]<=0||S.air<1)+bt(c.cl[i]?"돌파 완료":"구역 돌파 도전 (20분 · 산소 1)","cchal()",z||c.cl[i]||S.air<1):bt(p.d?"탐사 완료":"왕의 보물고에 들어간다 (20분 · 산소 1)","cfin()",z||p.d||!c.cl[3]||S.air<1);
