h4:ch("독이 있는 발광 해파리 떼가 통로를 가득 메웠다.",[["움직임을 살피며 틈으로 지난다",.4,"해파리 사이를 조용히 빠져나갔다.>?","촉수에 스쳤다.|p:-10;o:-1>?","망꾼"],["그물로 해파리를 모아 치운다",.4,"그물로 해파리를 한쪽으로 몰아냈다.>?","그물이 찢겼다.|p:-6;o:-1>?","낚시꾼"],["약초즙을 바르고 돌파한다",.4,"독을 막고 지나갔다.>?","약효가 모자라 독이 번졌다.|p:-12;o:-1>?","요리사"]]),
h5:ch("산호 틈에서 거대한 문어가 눈을 뜨며 촉수를 뻗는다.",[["미끼를 던져 시선을 돌린다",.4,"문어가 미끼를 쫓는 틈에 지나갔다.>?","촉수에 휘감겼다.|p:-12;o:-1>?","낚시꾼"],["숨죽이고 곁을 지난다",.35,"문어는 잠에서 덜 깨 있었다.>?","문어와 눈이 마주쳤다.|p:-10;o:-1>?","망꾼"],["작살로 쫓아낸다",.3,"작살에 놀란 문어가 도망쳤다.>?","촉수에 맞아 튕겨 나갔다.|p:-14;o:-1>?","잠수부"]]),
