function landBtn(z){const e=entry(S.dk),w=I[S.dk];return e.deny&&S.pass!==S.dk?`<div class="sub sm">${e.why}</div>`+bt(`벌금 ${e.fine}G 내고 입장`,"payFine()",z||S.gold<e.fine):bt("상륙 — "+w.n,"land()",z,1)}
