function bsolve(i){const w=wI(),b=w.bl[i];if(!b||b.st||S.act||S.pend)return;start("현장 소탕",18,()=>{S.qn=b.name;S.curB=b;sc(pick(["bt1","bt2"]))})}
function baccept(i){const w=wI(),b=w.bl[i];if(S.quests.length>=3)return say("동시에 맡을 수 있는 수배는 3건까지다.");const sp=seaSpot(),q={bid:b.id,name:b.name,crime:b.crime,reward:b.reward,home:S.isl,state:"accepted",poi:{t:"수배",n:b.name+"의 배",x:sp[0],y:sp[1],f:1,d:0,h:1,q:b.id}};PO.push(q.poi);S.quests.push(q);ct("acc");b.st=1;say(`수배 수락: ${b.name} (${b.crime}). 바다 어딘가에서 추적해 포박하고 이 마을로 데려오면 ${b.reward}골드와 명예를 받는다. 해도에 ⚑ 표시가 생겼다.`);renderAll()}
function bturn(i){const w=wI(),b=w.bl[i],q=S.quests.find(x=>x.bid===b.id&&x.state==="captured");if(!q)return;const k="포박된 "+q.name,src=S.inv[k]>0?S.inv:S.sto[k]>0?S.sto:null;if(!src)return say("포박한 수배자가 소지품이나 창고에 없다.");src[k]--;const v=Math.round(q.reward*(1+M("gold")));S.gold+=v;S.hon+=5;b.st=2;S.quests=S.quests.filter(x=>x!==q);say(`${q.name}을(를) 경비대에 인도했다. 보상 ${v}골드, 명예 +5.`);renderAll()}
function boardHTML(w,z){const row=(l,r)=>`<div class="row"><span>${l}</span><span>${r}</span></div>`;return `<h2>수배 게시판</h2>`+(w.bl.length?w.bl.map((b,i)=>{const l=`<b>${b.name}</b> <span class="sub sm">${b.crime} · 보상 ${b.reward}G · ${b.kind==="quest"?"추적 의뢰":"현장 소탕"}</span>`;
 if(b.st===2)return row(l,'<span class="sub">처리 완료</span>');
 if(b.kind==="instant")return row(l,bt("현장 소탕 (18분)",`bsolve(${i})`,z));
 const q=S.quests.find(x=>x.bid===b.id);if(!q)return row(l,bt("수배 수락",`baccept(${i})`,z));
 return q.state==="captured"?row(l,bt(`수배자 인도 (+${b.reward}G)`,`bturn(${i})`,z)):row(l,'<span class="sub">추적 중 — 바다 어딘가</span>')}).join(""):"<div class='sub'>붙어 있는 수배서가 없다.</div>")}
