function assignSP(){const q_=n=>Math.floor(sr()*n);Object.entries(SP).forEach(([id,sp])=>{let c=I.filter((w,i)=>i>0&&!w.sp&&w.t===sp.t);if(!c.length){const q=I.filter((w,i)=>i>0&&!w.sp&&w.t==="무인도");if(!q.length)return;const w=q[q_(q.length)];w.t=sp.t;if(sp.t==="마을")w.bl=genBoard();c=[w]}c[q_(c.length)].sp=id})}
