const WEP={"룬 작살":[19,520,"고대 문양이 새겨진 작살. 바다 괴물이 움찔한다."],"식칼":[4,40,"주방장이 쓰던 튼튼한 식칼. 자르기엔 칼이 최고다."],"망치":[5,60,"정비공의 망치. 두드릴 곳은 늘 많다."],"녹슨 단검":[3,25,"날이 무뎌진 단검. 없는 것보다는 낫다."],"작살":[5,45,"고래잡이용 작살. 바다 생물을 상대로 쓸 만하다."],"커틀러스":[8,90,"선원들이 즐겨 쓰는 휜 칼."],"도끼":[10,110,"갑판에서도 나무 위에서도 쓸모 있다."],"머스킷":[13,200,"한 발이 묵직한 장총. 화약 냄새가 난다."],"선장의 사브르":[16,320,"장식이 화려한 명검."]};
const ARM={"강철 갑옷":[9,350,"무겁지만 든든한 해군 갑옷."],"가죽 조끼":[2,40,"질긴 가죽으로 기운 조끼."],"선원의 방패":[4,85,"나무와 쇠로 만든 둥근 방패."],"비늘 갑옷":[6,180,"바다 생물의 비늘로 엮은 갑옷."]};
const JUNK={"녹슨 깡통":[1,"바닥이 뚫린 깡통."],"찢어진 그물":[2,"수리하기엔 너무 낡았다."],"한쪽 장화":[2,"짝을 잃은 장화."],"젖은 신문":[1,"글자가 번져 읽을 수 없다."],"부러진 낚싯대":[3,"누군가의 불운이 남아 있다."],"조개껍데기 더미":[1,"속이 텅 비었다."]};
Object.entries(WEP).forEach(([k,v])=>SELL[k]=Math.floor(v[1]/2));Object.entries(ARM).forEach(([k,v])=>SELL[k]=Math.floor(v[1]/2));Object.entries(JUNK).forEach(([k,v])=>SELL[k]=v[0]);Object.assign(SELL,{"크라켄의 촉수":80,"세이렌의 비늘":90,"상어 고기":18});
const wAtk=()=>S.eq.w&&WEP[S.eq.w]?WEP[S.eq.w][0]:0,aDef=()=>S.eq.a&&ARM[S.eq.a]?ARM[S.eq.a][0]:0;
function equip(k){if(!(S.inv[k]>0))return;if(WEP[k])S.eq.w=k;else if(ARM[k])S.eq.a=k;say(k+"을(를) 장착했다.");renderAll()}
function unequip(t){S.eq[t]=null;renderAll()}
function useHerb(){if(!(S.inv.약초>0))return;S.inv.약초--;const n=Math.round(20*(1+.12*(lv("med")-1)));S.hp=Math.min(hpm(),S.hp+n);S.ef=S.ef.filter(e=>e.id!=="독");addXp("med",3);say(`약초로 상처를 치료했다. 체력 +${n} (의료 경험 +3)`);renderAll()}
function useGear(k){if(!(S.inv[k]>0))return;S.inv[k]--;if(k==="붕대"){const n=Math.round(35*(1+.12*(lv("med")-1)));S.hp=Math.min(hpm(),S.hp+n);S.ef=S.ef.filter(e=>e.id!=="부상");say(`붕대를 감았다. 체력 +${n}, 부상이 낫는다.`)}else{S.ef=S.ef.filter(e=>e.id!=="독");say("해독제를 마셨다. 독이 풀린다.")}addXp("med",2);renderAll()}
function brew(kind){if(S.act)return;const need=kind==="붕대"?3:4;if(lv("med")<need)return say(`조제하려면 의료 Lv ${need}이(가) 필요하다.`);
 if(kind==="붕대"){if(!(S.inv.약초>=2))return say("약초가 2개 필요하다.")}else if(!(S.inv.약초>=1&&S.inv.소금>=1))return say("약초 1개와 소금 1개가 필요하다.");
 start("조제",9,()=>{if(kind==="붕대"){if(!(S.inv.약초>=2))return;S.inv.약초-=2}else{if(!(S.inv.약초>=1&&S.inv.소금>=1))return;S.inv.약초--;S.inv.소금--}add(kind);ct("brew");addXp("med",4);say(`${kind}을(를) 만들었다. (의료 경험 +4)`)})}
function sharpen(){if(S.act||!S.eq.w)return;start("무기 연마",12,()=>{addEf("날섬",360);addXp("fix",2);ct("sharp");say(`${S.eq.w}의 날을 갈았다. 6시간 동안 공격력이 오른다.`)})}
function itemInfo(k){const wp=WEP[k],am=ARM[k],jk=JUNK[k];let h;
 if(wp||am||jk){const eqd=(wp&&S.eq.w===k)||(am&&S.eq.a===k);h=`<h2 style="margin-top:0">${k}</h2><div class="sub sm">${wp?"무기":am?"방어구":"잡동사니"} · 소지 ${S.inv[k]||0}${S.sto[k]?` · 창고 ${S.sto[k]}`:""}${eqd?" · 장착 중":""}</div><p>${wp?wp[2]:am?am[2]:jk[1]}</p>`+(wp?`<div class="row"><span>공격력</span><span>+${wp[0]}</span></div>`:"")+(am?`<div class="row"><span>방어력</span><span>+${am[0]}</span></div>`:"")+`<div class="row"><span>기준 판매가</span><span>${SELL[k]} G</span></div><div class="row"><span>현재 판매가</span><span>${S.isl!==null?pr(k)+" G ("+I[S.isl].n+")":"섬에 상륙하면 확인"}</span></div>`+((wp||am)&&S.inv[k]>0?(eqd?bt("장착 해제",`unequip('${wp?"w":"a"}')`):bt("장착",`equip('${k}')`)):"")}
 else h=itemInfo0(k);
 if(k==="붕대")h+=bt("붕대 감기 (체력 +35, 부상 치료)","useGear('붕대')",!(S.inv.붕대>0));if(k==="해독제")h+=bt("해독제 마시기 (독 해제)","useGear('해독제')",!(S.inv.해독제>0));if(k==="약초")h+=bt("약초로 치료 (체력 +20, 독 해제)","useHerb()",!(S.inv.약초>0));return h}
/* ================= 숙련 레벨 / 상태 효과 ================= */
const lvOf=x=>Math.min(10,Math.floor(Math.sqrt(x/12))+1),LVN={cook:"요리",fight:"전투",med:"의료",fix:"정비"};
const lv=k=>lvOf((S.xp&&S.xp[k])||0);
function addXp(k,n){const a=lv(k);S.xp[k]=(S.xp[k]||0)+n;const b=lv(k);if(b>a)say(`${LVN[k]} 숙련도가 ${b}레벨이 되었다!`)}
const EFX={날섬:{g:1,d:"무기를 갈아 두었다. 전투 공격력이 오른다.",m:{atk:2},r:0},부상:{g:0,d:"다쳤다. 낚시와 잠수가 둔해지고 체력이 더 이상 차오르지 않는다.",m:{dive:-.2,fish:-.1},r:-.035},독:{g:0,d:"독이 퍼진다. 체력이 서서히 닳는다.",m:{},r:-.1},행복:{g:1,d:"기분이 좋다. 행운과 낚시 솜씨가 오르고 체력이 천천히 찬다.",m:{luck:.1,fish:.1},r:.03},포만:{g:1,d:"배가 든든하다. 허기가 천천히 닳는다.",m:{hun:-.3},r:0},취기:{g:0,d:"알딸딸하다. 흥정은 잘 되지만 시야가 흐리다.",m:{gold:.08,vis:-1},r:0}};
const efMod=k=>S.ef.reduce((a,e)=>a+(((EFX[e.id]||{}).m||{})[k]||0),0);
function addEf(id,min){const d=EFX[id];if(!d)return;if(!d.g)min=Math.max(30,Math.round(min*(1-.05*(lv("med")-1))));const e=S.ef.find(x=>x.id===id),u=S.t+min;if(e)e.until=Math.max(e.until,u);else S.ef.push({id,until:u})}
function efTick(dt){let rg=0;S.ef=S.ef.filter(e=>{if(S.t>=e.until){say("효과가 사라졌다: "+e.id);return false}rg+=(EFX[e.id]||{r:0}).r;return true});if(rg)S.hp=Math.min(hpm(),S.hp+rg*dt)}
function efHTML(){return S.ef.map(e=>{const d=EFX[e.id];if(!d)return"";const m=Math.max(1,Math.round(e.until-S.t));return `<span class="chip ${d.g?"g":"b"}" title="${d.d}">${e.id} ${m>=60?Math.round(m/60)+"시간":m+"분"}</span>`}).join("")}
/* ================= 턴제 전투 (아군 목록 b.al 에 선원이 함께 선다) ================= */
const MON={serpent:{n:"바다뱀",en:[["바다뱀",110,13,2,"bite"]],win:"g:140;a;m:1",lose:"h:12",xp:8},crab:{n:"거대 집게게",en:[["거대 집게게",95,10,5,""]],win:"g:70;i:게:3;i:조개:2",lose:"h:8",xp:7},ghostp:{n:"유령 해적단",en:[["유령 선장",85,12,3,"boss"],["유령 선원",35,7,1,""],["유령 선원",35,7,1,""]],win:"g:160;a;m:2",lose:"h:10",xp:11},shark:{n:"거대 상어",en:[["거대 상어",70,12,2,"bite"]],win:"g:60;i:상어 고기:2",lose:"h:6",xp:6},jelly:{n:"해파리 떼",en:[["해파리",25,5,0,"jelly"],["해파리",25,5,0,"jelly"],["해파리",25,5,0,"jelly"]],win:"g:30",lose:"",xp:5},siren:{n:"세이렌",en:[["세이렌",80,9,1,"siren"]],win:"g:150;i:세이렌의 비늘:1;m:1",lose:"",xp:9},kraken:{n:"크라켄",en:[["크라켄",150,14,3,"kraken"],["촉수",40,8,0,"tent"],["촉수",40,8,0,"tent"]],win:"g:300;i:크라켄의 촉수:2;a;m:3",lose:"h:25",xp:16},pirates:{n:"해적선 습격",en:[["해적 두목",60,10,2,"boss"],["해적",32,6,1,""],["해적",32,6,1,""]],win:"g:90;m:3;i:커틀러스:1",lose:"h:8",xp:10},outlaw:{n:"수배자 {n}",en:[["{n}",75,10,2,"boss"],["부하",32,6,1,""],["부하",32,6,1,""]],win:"k:1;m:2",lose:"z:1",xp:10},outlawI:{n:"수배자 {n}",en:[["{n}",75,10,2,"boss"],["부하",32,6,1,""],["부하",32,6,1,""]],win:"w:1;m:4",lose:"",xp:10}};
function startBattle(key){const m=MON[key];if(!m||S.bt||S.over)return;const nm=x=>x.replace(/\{n\}/g,S.qn||"수배자"),seed=Math.floor(rnd()*1e9);
 const en=m.en.map(([n,hp,atk,def,sk])=>({n:nm(n),hp:Math.round(hp*thr()),mhp:Math.round(hp*thr()),atk:Math.round(atk*thr()*10)/10,def,sk,st:{}})),al=[{n:"나",me:1,st:{}}];
 S.bt={key,t:nm(m.n),seed,r:rng(seed),acts:[],en,al,tg:0,rd:1,log:[nm(m.n)+"과(와)의 전투가 시작됐다!"],win:m.win,lose:m.lose,xp:m.xp,def:false,cd:{smash:0,aid:0},done:0};
 if(S.isl===null&&!S.inC)S.view="deck";say("— 전투 시작: "+S.bt.t);renderAll()}
const bRoll=()=>S.bt.r(),bl=t=>{const b=S.bt;b.log.push(t);if(b.log.length>40)b.log.shift()};
const bDmg=(a,d)=>Math.max(1,Math.round(a*(.85+.3*bRoll())-d)),hpv=x=>x.me?S.hp:x.hp,mhv=x=>x.me?hpm():x.mhp,aliveL=a=>a.filter(x=>hpv(x)>0);
function bHurt(x,d,src){if(x.me)S.hp=Math.max(0,S.hp-d);else x.hp=Math.max(0,x.hp-d);bl(`${src}의 공격! ${x.n}에게 ${d} 피해.`)}
function bHit(e,d,src){e.hp=Math.max(0,e.hp-d);bl(`${src}의 공격! ${e.n}에게 ${d} 피해.${e.hp<=0?" 쓰러뜨렸다!":""}`)}
function bHeal(x,n,src){if(x.me)S.hp=Math.min(hpm(),S.hp+n);else x.hp=Math.min(x.mhp,x.hp+n);bl(`${src}: ${x.n}의 체력이 ${n} 회복됐다.`)}
const bWeak=()=>aliveL(S.bt.al).sort((x,y)=>hpv(x)/mhv(x)-hpv(y)/mhv(y))[0];
function btTg(i){const b=S.bt;if(b&&b.en[i]&&b.en[i].hp>0){b.tg=i;renderAll()}}
function eTurn(e){const b=S.bt;if(e.hp<=0)return;const al=aliveL(b.al);if(!al.length)return;if(e.st.stun>0)return bl(`${e.n}은(는) 움직이지 못한다.`);const tg=al[Math.floor(bRoll()*al.length)];
 if(e.sk==="siren"&&bRoll()<.4){tg.st.stun=2;return bl(`세이렌의 노래! ${tg.n}의 정신이 흐려진다 (한 턴 행동 불가).`)}
 let a=e.atk*(e.sk==="boss"&&e.hp<e.mhp*.35?1.3:1),d=bDmg(a,tg.me?aDef():0);if(tg.me&&b.def)d=Math.round(d*.5);bHurt(tg,d,e.n);
 if(e.sk==="jelly"&&tg.me&&bRoll()<.5){addEf("독",240);bl("독침에 쏘였다! (독 효과)")}
 if((e.sk==="kraken"||e.sk==="tent")&&bRoll()<.3){tg.st.bind=2;bl(`${tg.n}이(가) 촉수에 휘감겼다 (도망 불가).`)}}
function bAct(kind){const b=S.bt;if(!b||b.done)return;const me=b.al[0],tg=(b.en[b.tg]&&b.en[b.tg].hp>0)?b.en[b.tg]:b.en.find(x=>x.hp>0);b.acts.push(kind);b.def=false;const atk=10+C.st.근력*1.5+wAtk()+efMod("atk")+2*(lv("fight")-1);
 if(kind==="flee"){if(!(me.st.bind>0)&&bRoll()<.55){bl("재빨리 물러났다!");return bEnd("flee")}bl(me.st.bind>0?"촉수에 묶여 도망칠 수 없다!":"도망치려 했지만 실패했다.")}
 else if(kind==="pass"){bl("흐려진 정신을 가다듬었다.")}
 else if(kind==="atk"){bHit(tg,bDmg(atk,tg.def),"나")}
 else if(kind==="smash"){bHit(tg,bDmg(atk*1.7,tg.def),"나(강타)");b.cd.smash=3}
 else if(kind==="def"){b.def=true;bl("방어 태세를 취했다.")}
 else if(kind==="heal"){if(!(S.inv.약초>0))return;S.inv.약초--;bHeal(bWeak(),Math.round(22*(1+.12*(lv("med")-1))),"약초");S.ef=S.ef.filter(e=>e.id!=="독");addXp("med",3)}
 else if(kind==="aid"){bHeal(bWeak(),Math.round(18*(1+.12*(lv("med")-1))),"응급처치");b.cd.aid=3;addXp("med",3)}
 if(b.en.every(x=>x.hp<=0))return bEnd("win");
if(b.en.every(x=>x.hp<=0))return bEnd("win");
 b.en.forEach(eTurn);if(S.hp<=0)return bEnd("lose");
 ["smash","aid"].forEach(k=>{if(b.cd[k]>0)b.cd[k]--});b.al.concat(b.en).forEach(x=>["stun","bind"].forEach(k=>{if(x.st[k]>0)x.st[k]--}));b.rd++;renderAll()}
function bEnd(kind){const b=S.bt;b.done=1;const t=b.t;
 if(kind==="win"){addXp("fight",b.xp);ct("win");say(`전투 승리! ${t}을(를) 물리쳤다. (전투 경험 +${b.xp})`);const r=fx(b.win);if(r)say("전리품 "+r);S.bt=null;flush()}
 else if(kind==="flee"){say(t+"에게서 도망쳤다.");if(/z:/.test(b.lose))fx(b.lose);S.bt=null}
 else{S.hp=Math.max(1,Math.round(hpm()*.3));S.t+=240;addEf("부상",600);say("전투에서 패배했다. 정신을 잃었다가 눈을 떠 보니 4시간이 지나 있었다. 다행히 잃은 물건은 없다.");const r=fx(b.lose||"");if(r)say(r);S.bt=null}
 renderAll()}
function rBattle(){const e=$("btl"),b=S.bt;if(!b){e.className="";e.innerHTML="";return}e.className="card pend";
 const bar=(v,m)=>`<div class="bar${v/m<.3?" w":""}"><i style="width:${Math.max(0,v/m*100)}%"></i></div>`;
 const en=b.en.map((x,i)=>`<div class="bt-row ${x.hp<=0?"dead":""} ${b.tg===i&&x.hp>0?"sel":""}" onclick="btTg(${i})"><div class="row"><span>${b.tg===i&&x.hp>0?"▶ ":""}${x.n}${x.st.stun>0?" ✦기절":""}</span><span class="sm">${Math.max(0,x.hp)}/${x.mhp}</span></div>${bar(x.hp,x.mhp)}</div>`).join("");
 const al=b.al.map(x=>{const v=hpv(x),m=mhv(x);return `<div class="${v<=0?"dead":""}"><div class="row"><span>${x.n}${x.role?` <span class="sub sm">${x.role}</span>`:""}${x.st.stun>0?" ✦혼란":""}${x.st.bind>0?" ✦속박":""}</span><span class="sm">${Math.max(0,Math.round(v))}/${m}</span></div>${bar(v,m)}</div>`}).join("");
 const me=b.al[0],fl=lv("fight"),ml=lv("med");
 const btn=me.st.stun>0?bt("정신을 차린다 (이번 턴 넘김)","bAct('pass')"):bt("공격","bAct('atk')")+bt(`강타${b.cd.smash>0?` (${b.cd.smash})`:""}`,"bAct('smash')",fl<3||b.cd.smash>0)+bt("방어","bAct('def')")+bt(`약초 치료 (${S.inv.약초||0})`,"bAct('heal')",!(S.inv.약초>0))+bt(`응급처치${b.cd.aid>0?` (${b.cd.aid})`:""}`,"bAct('aid')",ml<3||b.cd.aid>0)+bt("도망","bAct('flee')");
 e.innerHTML=`<h2 style="margin-top:0">전투 — ${b.t} · 라운드 ${b.rd}</h2><div class="two"><div><h3>적 <span class="sub sm">(눌러서 대상 선택)</span></h3>${en}</div><div><h3>나</h3>${al}</div></div><div style="margin-top:8px">${btn}</div><div class="sub sm bt-log">${b.log.slice(-6).map(l=>`<div>${l}</div>`).join("")}</div>`}
