function up(){const n=SH[S.lv+1];if(!n||S.gold<yc(n))return say("골드가 모자라거나 이미 최대 단계다.");S.gold-=yc(n);S.lv++;S.hull=hm();say("배를 「"+n.n+"」(으)로 개조했다!");renderAll()}
