function setCourse(x,y,l){const p=findPath(S.x,S.y,x,y);if(!p||!p.length){say("그쪽으로 갈 수 있는 바닷길이 없다.");return renderAll()}S.path=p;S.tx=p[p.length-1][0];S.ty=p[p.length-1][1];S.sail=true;S.man=false;S.dk=-1;say(l?l+"(으)로 항로를 잡았다. 육지를 돌아 항해한다.":"새 항로를 잡았다.");renderAll()}
