function tUp(d){S.lv=Math.max(0,Math.min(3,S.lv+d));S.hull=hm();say("[테스트] 배 단계 → "+SH[S.lv].n);renderAll()}
function rTest(){$("tst").innerHTML=bt("해저 도시로 이동","tpPO('도시')")+bt("보물로 이동","tpPO('보물')")+bt("유령선 호출","ghost()",!!S.pend)+bt("배 단계 +1","tUp(1)")+bt("배 단계 −1","tUp(-1)")+bt("허기·체력 회복","S.hun=100;S.hp=hpm();renderAll()")+bt("전투: 크라켄","startBattle('kraken')",!!S.bt)+bt("전투: 세이렌","startBattle('siren')",!!S.bt)+bt("전투: 해적","startBattle('pirates')",!!S.bt)+bt("전투: 해파리","startBattle('jelly')",!!S.bt)+bt("전투: 상어","startBattle('shark')",!!S.bt)+bt("명예 +20","S.hon+=20;renderAll()")+bt("악명 +20","S.inf+=20;renderAll()")+`<select onchange="if(this.value!=='')tpTo(I[this.value].dx,I[this.value].dy,+this.value)"><option value="">섬으로 이동…</option>${I.map((w,i)=>`<option value="${i}">${w.n} (${w.t})</option>`).join("")}</select>`}
/* TEST-END */
